import registry


def run(name, *args):
    """Run the plugin called `name`. Plugin names are case-insensitive."""
    # The registry stores plugins with exact case, but lookup is case-insensitive
    # We need to find the plugin by comparing lowercased names
    fn = None
    for plugin_name, plugin_func in registry._PLUGINS.items():
        if plugin_name.lower() == name.lower():
            fn = plugin_func
            break

    if fn is None:
        raise KeyError(f"no plugin {name!r}")
    return fn(*args)
```

